{
  "themes": [
    {
      "name": "Comply v2 Feature Adoption",
      "definition": "Calls where Aegis staff demonstrate or pitch the newly released Aegis Comply v2 capabilities, focusing on multi-framework support and on-demand reporting to accelerate customer audit cycles.",
      "distinguishing": "Focuses on commercial positioning, feature demos, and customer onboarding for new compliance reporting capabilities, rather than managing internal audit evidence or resolving billing errors.",
      "owner": "sales / account manager",
      "actionable_because": "Account managers can identify accounts preparing for upcoming audits and schedule targeted Comply v2 upgrade demos and cross-sell campaigns.",
      "meeting_ids": ["036285", "16916D", "571940", "754FB8", "E7A00D", "EB4171"],
      "evidence": [
        {
          "meeting_id": "036285",
          "quote": "So with Comply v2 \u2014 and this just went GA two days ago, April 7th \u2014 we've built out on-demand reporting that's fully mapped to PCI DSS controls."
        },
        {
          "meeting_id": "16916D",
          "quote": "The output is a structured PDF \u2014 it's formatted specifically for auditor consumption, so it's got your control mapping, your evidence artifacts, timestamps, everything organized by control category."
        },
        {
          "meeting_id": "571940",
          "quote": "So I'm clicking on PCI DSS here, you select your scope \u2014 in your case this would be your cardholder data environment, your point of sale systems, whatever you've got mapped \u2014 and then you just hit generate, and watch how fast this comes back."
        }
      ]
    },
    {
      "name": "Detect Pipeline Outage Fallout",
      "definition": "Calls discussing the operational, commercial, or compliance repercussions of the March cascading failure and event ingestion loss in Aegis Detect.",
      "distinguishing": "Deals broadly with customer churn risk, post-incident reviews, SLA credits, and competitive pressure stemming specifically from the March multi-hour ingestion outage.",
      "owner": "engineering lead",
      "actionable_because": "Engineering leads must prioritize pipeline resilience, redundant nodes, circuit breaker patterns, and post-incident technical documentation to prevent churn and SLA penalties.",
      "meeting_ids": ["31FAFD", "4DC695", "7315E7", "7814CB", "970775", "C898C9", "DC89B6", "EA6697", "EB4171"],
      "evidence": [
        {
          "meeting_id": "4DC695",
          "quote": "What happened was we had a cascading failure that started around 11 PM on the 10th and by about 5 AM on the 11th we had essentially zero threat monitoring visibility for customers on the Detect module."
        },
        {
          "meeting_id": "7315E7",
          "quote": "The last event we see in the dashboard is timestamped at 7:14 AM this morning and it is now almost 10:30 and I have a team of analysts sitting here staring at a dead screen."
        },
        {
          "meeting_id": "7814CB",
          "quote": "We're implementing redundant processing nodes and we're adding a circuit breaker pattern so that if one node degrades, traffic gets redistributed rather than causing a full outage."
        }
      ]
    },
    {
      "name": "Identity Directory Integration Failures",
      "definition": "Calls involving operational failures and authentication breakages when synchronizing or federating Aegis Identity with corporate identity directories.",
      "distinguishing": "Focuses on active technical breakdowns like LDAP handshake errors or SAML certificate rotation bugs affecting employee access, rather than prospective onboarding planning or feature gap requests.",
      "owner": "support lead",
      "actionable_because": "Support leads can create specific troubleshooting playbooks for SSL/TLS certificates and push for UI error messaging improvements to reduce time-to-resolution on directory connector cases.",
      "meeting_ids": ["099E75", "B62A59"],
      "evidence": [
        {
          "meeting_id": "099E75",
          "quote": "If your certificate was issued by an internal certificate authority, our connector doesn't inherently trust that CA. You need to upload your internal CA's root certificate into Aegis Identity so that we can validate the chain."
        },
        {
          "meeting_id": "B62A59",
          "quote": "We rotated our SAML signing certificate yesterday, standard procedure, we do this every six months, and after the rotation a significant portion of our users are getting authentication failures when they try to SSO into our internal tools."
        }
      ]
    },
    {
      "name": "Threat Detection False Positives",
      "definition": "Calls where customers seek assistance tuning detection sensitivity, rulesets, and baselines due to an overwhelming volume of false alerts and SOC fatigue.",
      "distinguishing": "Concerns noisy, improperly calibrated, or patch-reset alert rules generating false positives, distinct from complete pipeline blindness or ingestion outages.",
      "owner": "product manager",
      "actionable_because": "Product managers can refine default baseline learning algorithms, prevent patches from wiping custom thresholds, and provide more intuitive location/work-schedule tuning controls.",
      "meeting_ids": ["3FB020", "657CF1"],
      "evidence": [
        {
          "meeting_id": "3FB020",
          "quote": "The false positive issue is honestly top of mind right now. Our SOC team is getting fatigued \u2014 they're seeing a ton of alerts that aren't actionable and it's starting to affect response times on the stuff that actually matters."
        },
        {
          "meeting_id": "657CF1",
          "quote": "The patch included updates to the behavioral detection engine and in some environments it's basically starting the learning period over from scratch."
        }
      ]
    },
    {
      "name": "Enterprise Audit Readiness Preparation",
      "definition": "Internal meetings dedicated to organizing, auditing, and validating control evidence across access, change management, and logging in advance of external regulatory or SOC 2 reviews.",
      "distinguishing": "Pertains to internal Aegis teams conducting evidence reviews and operational checks for their own corporate audits, rather than selling compliance tools to customers.",
      "owner": "engineering lead",
      "actionable_because": "Engineering leads can enforce automated CI/CD deployment gates, standardize log retention policies, and remediate integration gaps to satisfy auditor requirements.",
      "meeting_ids": ["25FEC8", "D10880"],
      "evidence": [
        {
          "meeting_id": "25FEC8",
          "quote": "Can we add a gate in the CI/CD pipeline so that anything touching production requires a ticket reference? Like, a hard gate, not just a reminder."
        },
        {
          "meeting_id": "D10880",
          "quote": "Really the reason I pulled everyone together today is we need to do a final walk-through of the SOC 2 Type II materials before we hand them off to the auditors, and honestly I'm \u2014 I'm feeling pretty good about where we landed."
        }
      ]
    },
    {
      "name": "Contract Renewals and Commercial Retention",
      "definition": "Commercial discussions regarding multi-year contract renewals, annual pricing uplifts, SLA credits for previous service disruptions, and competitive retention.",
      "distinguishing": "Focuses on commercial terms, licensing structures, pricing negotiations, and retention strategies, rather than routine technical support or initial product demos.",
      "owner": "sales / account manager",
      "actionable_because": "Sales managers can structure renewal concessions, multi-module bundles, and enhanced SLA terms to protect recurring revenue against competitor offers.",
      "meeting_ids": ["31FAFD", "C898C9", "E7A00D", "EA6697"],
      "evidence": [
        {
          "meeting_id": "31FAFD",
          "quote": "We're proposing a renewal of both of those, same tier, with a three percent uplift which is honestly below our standard rate increase \u2014 and I'll explain why in a second."
        },
        {
          "meeting_id": "C898C9",
          "quote": "So your current contract has a 99.5% uptime SLA for Detect, and the six-hour outage did breach that. I'm going to be honest with you \u2014 I've been working with our team on a service credit for the affected period, and I have something concrete to bring to you today."
        },
        {
          "meeting_id": "EA6697",
          "quote": "We're proposing 99.9% uptime on Detect, which is up from the 99.5% that was in your current contract. And there are remediation credits tied to that if we fall below."
        }
      ]
    }
  ],
  "product_areas": [
    {
      "name": "Aegis Comply",
      "meeting_ids": ["036285", "16916D", "2F2C03", "31FAFD", "571940", "754FB8", "94B6C4", "C898C9", "D10880", "E7A00D", "EA6697", "EB4171"],
      "evidence": [
        {
          "meeting_id": "036285",
          "quote": "So with Comply v2 \u2014 and this just went GA two days ago, April 7th \u2014 we've built out on-demand reporting that's fully mapped to PCI DSS controls."
        },
        {
          "meeting_id": "571940",
          "quote": "Yeah that's a really common thing we're hearing, and that's kind of the whole value prop of pulling it into Aegis Comply \u2014 so let me show you the PCI DSS report generation since that's what's most relevant for you right now."
        }
      ]
    },
    {
      "name": "Aegis Detect",
      "meeting_ids": ["31FAFD", "3FB020", "4DC695", "657CF1", "7315E7", "7814CB", "970775", "C898C9", "DC89B6", "EA6697", "EB4171"],
      "evidence": [
        {
          "meeting_id": "3FB020",
          "quote": "So the plan for today is \u2014 we want to walk through your current Aegis Detect configuration, understand what alert thresholds you have set, talk about any false positive pain points you're running into, and then start mapping out what a tuned detection profile looks like for a financial services environment like yours."
        },
        {
          "meeting_id": "7315E7",
          "quote": "The event feed in Aegis Detect, it just... stopped. No alerts, no events, nothing."
        }
      ]
    },
    {
      "name": "Aegis Protect",
      "meeting_ids": ["71D752", "A9FF60"],
      "evidence": [
        {
          "meeting_id": "71D752",
          "quote": "And that's actually one of the areas where Aegis Protect really shines \u2014 you get that single pane of glass across your hybrid environment."
        },
        {
          "meeting_id": "A9FF60",
          "quote": "So I pulled up the case before hopping on \u2014 looks like you're looking at granular restore capabilities within Aegis Protect, is that the right starting point?"
        }
      ]
    },
    {
      "name": "Aegis Identity",
      "meeting_ids": ["099E75", "94B6C4", "973B16", "B62A59"],
      "evidence": [
        {
          "meeting_id": "099E75",
          "quote": "The Aegis Identity LDAP connector needs outbound access on port 389 for standard LDAP or 636 for LDAPS \u2014 are you running LDAPS by any chance?"
        },
        {
          "meeting_id": "973B16",
          "quote": "And Aegis Identity handles that really well \u2014 you can set up conditional access policies that treat contractors differently from full-time staff, different MFA requirements, session timeouts, all of that."
        }
      ]
    }
  ],
  "other_note": "Calls 2F2C03 (billing proration issue for Comply v2), 71D752 (implementation kickoff for Protect), 94B6C4 (feature request for hierarchical IAM roles in Identity), 973B16 (kickoff for Identity SSO/MFA onboarding), and A9FF60 (feature request for granular file-level restore in Protect) represent isolated single-call scenarios not covered by the proposed multi-call themes."
}
